.ds-scope {font-family:inherit;font-size:0.875rem;line-height:1.5;color:var(--foreground,#172624)} .ds-scope button,.ds-scope input {font:inherit} .ds-scope button {
  cursor: pointer;
  border: 1px solid var(--border, #dce4df);
  border-radius: 7px;
  padding: 0.55rem 0.8rem;
  background: var(--background, #fff);
  color: var(--foreground, #172624);
  min-height: 40px;
  white-space: nowrap;
  transition: background 160ms ease-out;
}
.ds-scope button:hover:not(:disabled) {
  background: var(--muted, #f3f6f4);
}
.ds-scope button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.ds-scope :is(button, input, select, textarea, [tabindex]):focus-visible {
  outline: 2px solid var(--primary, #21604b);
  outline-offset: 3px;
}
.ds-scope .ds-primary {
  background: var(--primary, #21604b);
  color: var(--primary-foreground, #fff);
  border-color: var(--primary, #21604b);
  font-weight: 600;
}
.ds-scope .ds-primary:hover:not(:disabled) {
  background: var(--primary, #21604b);
  filter: brightness(0.92);
}
@media(prefers-reduced-motion:reduce){.ds-scope *{transition:none!important}}

