.ds-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  border-bottom: 1px solid var(--border, #dce4df);
  padding-bottom: 1rem;
}
.ds-filters button {
  border-color: transparent;
  padding: 0.4rem 0.65rem;
  color: var(--muted-foreground, #53645e);
}
.ds-filters button[aria-pressed="true"] {
  color: var(--primary-foreground, #fff);
  background: var(--primary, #21604b);
  font-weight: 600;
}
.ds-filters button[aria-pressed="true"]:hover {
